// Paginated, incremental pull of status=new leads created since the last successful
// run — `collectedAfter` filters on leads.createdAt (application/leads/filters.schema.ts),
// `sort=oldest` walks the same ordering the cursor assumes so paging is deterministic.
// The watermark is captured as `runStartedAt` BEFORE fetching (not after), so a lead
// created mid-run is simply picked up next tick instead of silently skipped.
//
// Known tradeoff: status=new means once a lead's status changes it drops off this
// export permanently, even if it later flips back to 'new'. Acceptable for a
// 'sheet of fresh leads to work' use case; revisit if that changes.
const staticData = this.getWorkflowStaticData('node');
const cursor = staticData.lastRunAt || '1970-01-01T00:00:00.000Z';
const runStartedAt = new Date().toISOString();

const baseUrl = `${$env.AVERONAI_APP_URL}/api/v1/leads`;
const pageSize = 100;
let page = 1;
let totalPages = 1;
const allLeads = [];

do {
  const url = `${baseUrl}?status=new&sort=oldest&collectedAfter=${encodeURIComponent(cursor)}&page=${page}&pageSize=${pageSize}`;
  const response = await this.helpers.httpRequestWithAuthentication.call(this, 'httpHeaderAuth', {
    method: 'GET',
    url,
    json: true,
    timeout: 30000,
  });
  allLeads.push(...response.page.items);
  totalPages = response.page.totalPages;
  page += 1;
} while (page <= totalPages);

staticData.lastRunAt = runStartedAt;

return allLeads.map((lead) => ({
  json: {
    id: lead.id,
    name: lead.name,
    leadType: lead.leadType,
    status: lead.status,
    buyerScore: lead.buyerScore,
    confidenceScore: lead.confidenceScore,
    propertyTypes: (lead.propertyTypes || []).join(', '),
    locations: (lead.locations || []).join(', '),
    budgetMin: lead.budgetMin,
    budgetMax: lead.budgetMax,
    budgetCurrency: lead.budgetCurrency,
    whatsapp: lead.contact && lead.contact.whatsapp || '',
    phone: lead.contact && lead.contact.phone || '',
    email: lead.contact && lead.contact.email || '',
    assignedToName: lead.assignedToName || '',
    createdAt: lead.createdAt,
    latestAppearanceAt: lead.latestAppearanceAt,
  },
}));
